[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; cd "E:\project\海外TK店铺广告投流数据自动化监测"; powershell -NoProfile -Command "
. .\scripts\qingquan-client.ps1
# unit test ConvertTo-QingquanIngestItems currency default USD
\$rows = @([pscustomobject]@{ date='2026-07-27'; store='Gardena'; storeId='1'; campaign='test'; spend=10; orders=1; roi=2; revenue=20; sourceUrl='http://x'; status='success'; currency='USD' })
\$items = ConvertTo-QingquanIngestItems -Rows \$rows -CollectedAt '2026-07-28T00:00:00+00:00'
if (\$items[0].payload.currency -ne 'USD') { throw \"expected USD got \$(\$items[0].payload.currency)\" }
Write-Host 'qingquan currency OK:' \$items[0].payload.currency

# unit test money convert helpers from run-multi-store by loading functions only is hard; inline replicate
function Convert-MoneyToTarget {
  param([double]\$Amount,[string]\$FromCurrency,[string]\$TargetCurrency,\$RatesToUsd)
  \$from = if (\$FromCurrency) { \$FromCurrency.ToUpperInvariant() } else { 'USD' }
  \$to = if (\$TargetCurrency) { \$TargetCurrency.ToUpperInvariant() } else { 'USD' }
  if (\$from -eq \$to) { return [math]::Round(\$Amount, 2) }
  \$rateFrom = 1.0; \$rateTo = 1.0
  if (\$RatesToUsd.ContainsKey(\$from)) { \$rateFrom = [double]\$RatesToUsd[\$from] }
  if (\$RatesToUsd.ContainsKey(\$to)) { \$rateTo = [double]\$RatesToUsd[\$to] }
  \$usd = \$Amount * \$rateFrom
  return [math]::Round(\$usd / \$rateTo, 2)
}
\$rates = @{ USD=1.0; GBP=1.27; EUR=1.08 }
\$a = Convert-MoneyToTarget -Amount 100 -FromCurrency USD -TargetCurrency USD -RatesToUsd \$rates
\$b = Convert-MoneyToTarget -Amount 100 -FromCurrency GBP -TargetCurrency USD -RatesToUsd \$rates
if (\$a -ne 100) { throw \"USD identity failed: \$a\" }
if (\$b -ne 127) { throw \"GBP convert failed: \$b\" }
Write-Host 'convert OK: 100 USD->USD=' \$a '; 100 GBP->USD=' \$b
"

