[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; Set-Location "E:\project\海外TK店铺广告投流数据自动化监测"; node -e "const fs=require('fs'); const s=fs.readFileSync('scripts/scrape-ads-page.js','utf8'); const fn=new Function(s.replace(/^\(function \(\) \{/,'return (function(){').replace(/\}\)\(\);\s*$/,'})();')); console.log('syntax ok, length', s.length)"; node -e "
// mock DOM-less currency helpers extracted
function detectCurrency(text) {
  const s = String(text ?? '');
  if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
  if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
  if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
  if (/\$|USD|美金|美元/i.test(s)) return 'USD';
  return null;
}
function parseNumber(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  let s = String(value).trim();
  if (!s || s === '-' || s === '—') return null;
  s = s.replace(/[,\s]/g, '').replace(/[¥\$€£￥]/g, '').replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '').replace(/%/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}
console.log(detectCurrency('\$171.08'), parseNumber('\$171.08'));
console.log(detectCurrency('£94.21'), parseNumber('£94.21'));
console.log(detectCurrency('171.08'), parseNumber('171.08'));
"

