[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ErrorActionPreference = 'Stop'
$cfgPath = 'E:\project\海外TK店铺广告投流数据自动化监测\config\stores.config.json'
$cfg = Get-Content $cfgPath -Raw -Encoding UTF8 | ConvertFrom-Json
$appId = $cfg.feishu.appId
$appSecret = $cfg.feishu.appSecret
$appToken = $cfg.feishu.appToken
$tableId = $cfg.feishu.tableId

# token
$body = @{ app_id = $appId; app_secret = $appSecret } | ConvertTo-Json
$tok = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' -ContentType 'application/json; charset=utf-8' -Body $body
if ($tok.code -ne 0) { throw "token failed: $($tok.msg)" }
$token = $tok.tenant_access_token
$headers = @{ Authorization = "Bearer $token" }

# fields
$fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$appToken/tables/$tableId/fields?page_size=100"
$fieldList = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers $headers
if ($fieldList.code -ne 0) { throw "fields failed: $($fieldList.msg)" }
$names = @($fieldList.data.items | ForEach-Object { $_.field_name })
Write-Host ("fields: " + ($names -join ', '))

# list all records
$all = [System.Collections.Generic.List[object]]::new()
$pageToken = $null
do {
  $listUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$appToken/tables/$tableId/records?page_size=500"
  if ($pageToken) { $listUrl += "&page_token=$([uri]::EscapeDataString($pageToken))" }
  $resp = Invoke-RestMethod -Method GET -Uri $listUrl -Headers $headers
  if ($resp.code -ne 0) { throw "list failed: $($resp.msg)" }
  $items = @()
  if ($resp.data.items) { $items = @($resp.data.items) }
  foreach ($it in $items) { $all.Add($it) }
  $hasMore = $false
  if ($null -ne $resp.data.has_more) { $hasMore = [bool]$resp.data.has_more }
  $pageToken = $null
  if ($resp.data.page_token) { $pageToken = [string]$resp.data.page_token }
  Write-Host ("listed batch={0} total_so_far={1} has_more={2}" -f $items.Count, $all.Count, $hasMore)
} while ($hasMore -and $pageToken)

Write-Host ("TOTAL_RECORDS={0}" -f $all.Count)

# sample first 3 dates
$dateField = $null
foreach ($n in @('日期','业务日期','date','Date')) {
  if ($names -contains $n) { $dateField = $n; break }
}
Write-Host ("dateField=$dateField")
$today = Get-Date
$todayStart = Get-Date -Year $today.Year -Month $today.Month -Day $today.Day -Hour 0 -Minute 0 -Second 0
$todayMs = [DateTimeOffset]::new($todayStart).ToUnixTimeMilliseconds()
Write-Host ("todayMs=$todayMs today=$($todayStart.ToString('yyyy-MM-dd'))")

$toDelete = [System.Collections.Generic.List[string]]::new()
$keep = 0
$noDate = 0
foreach ($rec in $all) {
  $rid = [string]$rec.record_id
  $fields = $rec.fields
  $dval = $null
  if ($dateField -and $fields.PSObject.Properties.Name -contains $dateField) {
    $dval = $fields.$dateField
  }
  # Feishu date is often unix ms number
  $isToday = $false
  if ($null -ne $dval -and $dval -ne '') {
    try {
      $ms = [int64]$dval
      # same calendar day as today (local)
      $dt = [DateTimeOffset]::FromUnixTimeMilliseconds($ms).LocalDateTime.Date
      if ($dt -eq $todayStart.Date) { $isToday = $true }
    } catch {
      # ignore parse fail -> treat as historical
    }
  } else {
    $noDate++
  }
  if ($isToday) { $keep++ } else { $toDelete.Add($rid) }
}

Write-Host ("toDelete={0} keepToday={1} noDateFieldAmongAll={2}" -f $toDelete.Count, $keep, $noDate)
if ($toDelete.Count -eq 0) {
  Write-Host 'Nothing to delete.'
  exit 0
}

# batch delete 500
$deleted = 0
$delUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$appToken/tables/$tableId/records/batch_delete"
for ($i = 0; $i -lt $toDelete.Count; $i += 500) {
  $chunk = @($toDelete.GetRange($i, [Math]::Min(500, $toDelete.Count - $i)))
  $payload = @{ records = $chunk } | ConvertTo-Json -Compress
  $bytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
  $dresp = Invoke-RestMethod -Method POST -Uri $delUrl -Headers $headers -ContentType 'application/json; charset=utf-8' -Body $bytes
  if ($dresp.code -ne 0) { throw "delete failed: code=$($dresp.code) msg=$($dresp.msg)" }
  $deleted += $chunk.Count
  Write-Host ("deleted_batch={0} deleted_total={1}" -f $chunk.Count, $deleted)
  Start-Sleep -Milliseconds 200
}
Write-Host ("DONE deleted={0} kept_today={1}" -f $deleted, $keep)

